package com.tenora365.config;import com.tenora365.entity.*;import com.tenora365.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration @Profile("!demo") public class DataSeeder{@Bean CommandLineRunner seed(SchoolRepository schools,UserRepository users,PasswordEncoder enc){return a->{if(users.count()==0){School s=new School();s.setName("TENORA365 Demo School");s.setCode("DEMO");s.setEmail("demo@tenora365.com");schools.save(s);User sa=new User();sa.setUsername("superadmin");sa.setFullName("TENORA365 Super Admin");sa.setRole("SUPER_ADMIN");sa.setPasswordHash(enc.encode(System.getenv().getOrDefault("SUPERADMIN_PASSWORD","Super@12345")));users.save(sa);User ad=new User();ad.setSchool(s);ad.setUsername("admin@demo.tenora365.com");ad.setFullName("Demo School Admin");ad.setRole("SCHOOL_ADMIN");ad.setPasswordHash(enc.encode(System.getenv().getOrDefault("DEMO_ADMIN_PASSWORD","Admin@12345")));users.save(ad);}};}}
